'use strict';
let wardrobeTab='awards',cashbackTab='cashback',marketTab='home',cashbackExpanded=false;
const wardrobeCatalog={
 awards:[...['Знайомство','Еліта','Попутник','','',''].map((name,i)=>({name,src:'assets/achievement-'+i+'.png'})),...['Лічильник','Господар','Маляр','8 диво','Апетит','Гурман'].map((name,i)=>({name,src:'assets/reference/award-extra-'+i+'.png'}))],
 hats:['Маска','Волт','Джек','Воїн','В дорогу','Ковбой'].map((name,i)=>({name,src:'assets/reference/hats-'+i+'.png'})),
 shirts:['Спайдер','Леон','Айрон','Космос','Маріо'].map((name,i)=>({name,src:'assets/reference/shirts-'+i+'.png'})),
 glasses:['','Автоматизатор','S.T.A.L.K.E.R.','Бусідо','Страж','Спортик'].map((name,i)=>({name,src:'assets/reference/glasses-'+i+'.png'}))
};
function wardrobeItems(){return (wardrobeCatalog[wardrobeTab]||[]).map((item,i)=>`<button data-action="wardrobe-item" data-index="${i}" class="${state.wardrobeSelection?.[wardrobeTab]===i?'selected':''}"><img src="${item.src}" alt="${esc(item.name)}"><span>${esc(item.name)}</span></button>`).join('')}
appearance=function(){return `<div class="wardrobe-layout"><div class="character-cover"><div class="toolbar"><button class="back" data-action="back" aria-label="Назад">${icon('arrow-left')}</button><button class="right" data-action="unlocked" aria-label="Відкриті речі">${icon('bag-fill')}</button></div><img src="assets/profile-character.png" alt="Персонаж із наданого відео"></div><div class="character-actions"><button data-action="photo-choice">${icon('image')}Замінити фото</button><button data-action="poster-page">${icon('download-simple')}Завантажити</button></div><div class="wardrobe-tabs">${[['awards','star-fill','Нагороди'],['hats','cat-fill','Головні убори'],['shirts','shopping-bag-fill','Одяг'],['glasses','gear','Окуляри']].map(([id,i,l])=>`<button data-action="wardrobe-tab" data-tab="${id}" class="${id===wardrobeTab?'selected':''}" aria-label="${l}">${icon(i)}</button>`).join('')}</div><div class="wardrobe-scroll"><div class="wardrobe-grid">${wardrobeItems()}</div></div></div>`};
actions['wardrobe-tab']=b=>{wardrobeTab=b.dataset.tab;document.querySelectorAll('.wardrobe-tabs button').forEach(x=>x.classList.toggle('selected',x.dataset.tab===wardrobeTab));$('.wardrobe-grid').innerHTML=wardrobeItems();$('.wardrobe-scroll').scrollTop=0};
actions['wardrobe-item']=b=>{state.wardrobeSelection??={};state.wardrobeSelection[wardrobeTab]=Number(b.dataset.index);persist().then(()=>{document.querySelectorAll('.wardrobe-grid button').forEach(x=>x.classList.toggle('selected',x===b))}).catch(e=>toast(e.message))};
actions.unlocked=()=>{const entries=Object.entries(state.wardrobeSelection||{}).map(([tab,index])=>wardrobeCatalog[tab]?.[index]).filter(Boolean);modal('Відкриті речі',entries.map(x=>`<div class="unlocked-row"><img src="${x.src}" alt=""><span>${esc(x.name)}</span></div>`).join('')||'<p class="info">Оберіть річ у колекції персонажа.</p>',null)};
actions['photo-choice']=()=>navigate('photoChoice');actions['poster-page']=()=>navigate('poster');
function photoChoicePage(poster=false){return `<div class="photo-choice-page"><div class="toolbar"><button class="back" data-action="nav" data-page="appearance" aria-label="Закрити">${icon('x')}</button></div><div class="choice-heading"><span>${icon('cat-fill')}</span><h1>${poster?'Завантажити':'Замінити фото'}</h1></div>${poster?'<img class="character-poster" src="assets/reference/character-poster.png" alt="Зображення персонажа">':`<div class="photo-circles"><div>${state.avatar?`<img src="${esc(state.avatar)}" alt="Фото профілю">`:icon('cat-fill')}</div><div><img src="assets/profile-character.png" alt="Персонаж"></div></div>`}<button class="choice-cta" data-action="${poster?'download-character':'avatar-info'}">${poster?'Завантажити':'Замінити фото'}</button></div>`}
actions['personal-info']=()=>navigate('personal');
function personalPage(){return toolbar('')+`<div class="page personal-page"><h1>Особисті дані та документи</h1><button class="personal-photo" data-action="avatar-info"><span class="avatar">${state.avatar?`<img src="${esc(state.avatar)}" alt="">`:icon('cat-fill')}</span><strong>Поставити нове фото</strong></button><section class="native-group">${[['Як до вас звертатися?',state.name,'chat-circle-fill','orange'],['Телефон',state.phone||'Не вказано','device-mobile','sky'],['Ваша ел. пошта',state.email||'Не вказано','receipt','purple']].map(([l,v,i,c])=>`<button class="personal-row" data-action="personal-admin-info"><span class="service-symbol ${c}">${icon(i)}</span><span><small>${l}</small>${esc(v)}</span></button>`).join('')}${button('personal-admin-info','Документи','receipt','Надайте нові або перегляньте надані')}${button('personal-admin-info','Персональні дані','users')}</section></div>`}
actions['personal-admin-info']=()=>inform('Особисті дані','Дані цього демо-профілю змінюються в окремій адмінці. Документи до банку не надсилаються.');
actions['card-details']=()=>navigate('cardDetails');
function cardDetailsPage(){return toolbar('')+`<div class="page details-page"><h1>Реквізити картки</h1><div class="details-shortcuts"><button data-action="international-details"><span class="service-symbol sky">${icon('arrow-square-in')}</span>Для поповнення<br>з-за кордону</button><button data-action="international-details"><span class="service-symbol green">${icon('wallet')}</span>Для отримання<br>виплат на mono</button></div><section class="native-group requisites"><h2>Для поповнення по Україні</h2><dl><dt>Отримувач</dt><dd>${esc(state.name)}</dd><dt>IBAN</dt><dd>${esc(state.iban||'Не вказано')}</dd><dt>ІПН/ЄДРПОУ</dt><dd>${esc(state.taxId||'Не вказано')}</dd><dt>Призначення платежу</dt><dd>Поповнення рахунку</dd></dl><button class="secondary" data-action="share-details">${icon('export')}Поділитися</button></section><section class="native-group">${button('email-details','Надіслати реквізити на ел. пошту','receipt')}${button('qr-details','QR-код реквізитів','circles-four-fill')}</section></div>`}
const requisitesText=()=>`ДЕМО · НЕ БАНК\n${state.name}\n${state.iban||'IBAN не вказано'}\n${activeCard().card}\nНе для реальних платежів`;
actions['share-details']=async()=>{const text=requisitesText();try{if(navigator.share)await navigator.share({title:'Демонстраційні реквізити',text});else{await navigator.clipboard.writeText(text);toast('Демо-реквізити скопійовано')}}catch(e){if(e.name!=='AbortError')toast('Копіювання недоступне')}};
actions['email-details']=()=>{location.href='mailto:?subject='+encodeURIComponent('Демонстраційні реквізити')+'&body='+encodeURIComponent(requisitesText())};
actions['qr-details']=()=>inform('QR-код реквізитів','У цьому демо банківський платіжний QR-код не формується. Реквізити можна скопіювати кнопкою «Поділитися».');
actions['international-details']=()=>inform('Реквізити картки','Це локальна демонстраційна картка. Міжнародні банківські реквізити не видаються.');
function statementPage(){const c=activeCard();return toolbar('')+`<div class="page statement-page"><h1>Виписка за карткою</h1><form id="statement-form"><section class="native-group"><h2>Картка</h2><div class="statement-card"><span class="stats-mini-card">${cardArtwork(c)}</span><span>${esc(c.account)}<small>${esc(c.card.slice(0,4))} **** **** ${esc(c.card.slice(-4))}</small></span></div></section><section class="native-group"><h2>Мова документа</h2><div class="statement-options"><label><input type="radio" name="language" value="uk" checked>Українська</label><label><input type="radio" name="language" value="en">Англійська</label></div></section><section class="native-group"><h2>Тип файлу</h2><div class="statement-options"><label><input type="radio" name="format" value="pdf" checked>PDF</label><label><input type="radio" name="format" value="csv">CSV</label><label><input type="radio" name="format" value="xlsx">XLS</label></div></section><section class="native-group statement-period"><h2>Період</h2><label>Від<input type="date" name="start" value="${today().slice(0,7)}-01" required></label><label>До<input type="date" name="end" value="${today()}" required></label><div class="button-group"><button type="button" class="small-button" data-action="statement-month" data-shift="0">За цей місяць</button><button type="button" class="small-button" data-action="statement-month" data-shift="-1">За минулий місяць</button></div></section><button class="primary" type="submit">Продовжити</button></form></div>`}
actions['statement-month']=b=>{const shift=Number(b.dataset.shift),date=new Date(),start=new Date(date.getFullYear(),date.getMonth()+shift,1),end=shift?new Date(date.getFullYear(),date.getMonth(),0):date;const iso=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;$('#statement-form [name=start]').value=iso(start);$('#statement-form [name=end]').value=iso(end)};
function renderStatement(data){const english=data.get('language')==='en',tx=txFor().filter(t=>t.date>=data.get('start')&&t.date<=data.get('end'));return `<article class="statement-paper"><div class="paper-watermark">ДЕМО · НЕ ПІДТВЕРДЖУЄ ОПЛАТУ</div><h1>${english?'Sample account statement':'Зразок виписки за карткою'}</h1><p>ДЕМО · НЕ БАНКІВСЬКИЙ ДОКУМЕНТ</p><p>${esc(state.name)} · ${esc(activeCard().account)}<br>${esc(data.get('start'))} — ${esc(data.get('end'))}</p><table><thead><tr><th>${english?'Date':'Дата'}</th><th>${english?'Description':'Операція'}</th><th>${english?'Amount, UAH':'Сума, ₴'}</th></tr></thead><tbody>${tx.map(t=>`<tr><td>${esc(t.date)}</td><td>${esc(t.title)}</td><td>${displayMoney(t.amount)}</td></tr>`).join('')}</tbody></table></article>`}
function bindStatement(){const form=$('#statement-form');if(!form)return;form.onsubmit=e=>{e.preventDefault();const f=new FormData(form);if(f.get('start')>f.get('end'))return toast('Перевірте період');const tx=txFor().filter(t=>t.date>=f.get('start')&&t.date<=f.get('end')),format=f.get('format');if(format==='pdf'){modal('Зразок виписки',renderStatement(f),null);$('#modal').dataset.kind='statement';const button=document.createElement('button');button.type='button';button.className='primary';button.textContent='Друк / зберегти PDF';button.onclick=()=>window.print();$('#fields').append(button)}else if(format==='csv'){const safe=s=>'"'+String(s).replace(/"/g,'""').replace(/^[=+@]/,"'$&")+'"';const lines=[['ДЕМО · НЕ БАНКІВСЬКИЙ ДОКУМЕНТ'],['Дата','Операція','Сума, UAH'],...tx.map(t=>[t.date,t.title,t.amount])];download(new Blob(['\ufeff'+lines.map(a=>a.map(safe).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}),'demo-statement.csv')}else{downloadXlsx(tx,f)}}}
async function downloadXlsx(tx,form){const query=new URLSearchParams({card:activeCard().id,start:form.get('start'),end:form.get('end'),language:form.get('language')});try{const r=await fetch('/api/statement.xlsx?'+query);if(!r.ok)throw Error();download(await r.blob(),'demo-statement.xlsx')}catch{toast('Не вдалося сформувати XLSX. Спробуйте CSV.')}}
function subscriptionsPage(){const list=state.subscriptions||[];return toolbar('Підписки та сервіси')+`<div class="page subscriptions-page">${list.map(s=>`<button class="native-group subscription-row" data-action="subscription" data-id="${s.id}"><span class="service-symbol green">${icon('credit-card')}</span><span><strong>${esc(s.title)}</strong><small>Дії з карткою</small><small class="subscription-date">Токен створено ${esc(s.date)}</small></span></button>`).join('')||empty('Підписок немає','Підписки для демо додаються в адмінці.','credit-card')}</div>`}
actions.subscription=b=>{const s=state.subscriptions.find(s=>s.id===b.dataset.id);inform(s.title,`Демонстраційний запис · ${esc(s.date)}<br><br>Сервіс не підключено до реальної картки.`)};
function platinumPage(){return `<div class="platinum-page"><div class="toolbar"><button class="back" data-action="back" aria-label="Закрити">${icon('x')}</button></div><img class="platinum-visual" src="assets/reference/platinum.png" alt="Платинова картка з відеореференсу"><h1>Платинова картка</h1><section class="native-group"><h2>Коли гарне стає найкращим</h2><p>Три дизайни картки на вибір. Елітні привілеї. Безпрецедентна безпека. Знижені тарифи</p></section><section class="native-group"><h2>Безкоштовні залізничні та авіаквитки</h2><p>Демонстраційний екран із відео. Реальні банківські привілеї у проєкті не надаються.</p></section><button class="premium-cta" data-action="platinum-info">Хочу картку platinum<small>Випуск: 500 ₴ · демо</small></button></div>`}
actions['platinum-info']=()=>inform('Платинова картка','Це демонстрація екрана з відео. Банківська картка не випускається, кошти не списуються.');
actions.plastic=()=>navigate('platinum');
const refinedCardPage=cardPage;
cardPage=function(){return refinedCardPage().replace('data-page="regular"','data-page="subscriptions"').replace('data-page="history"','data-page="statement"')};
// Cashback uses horizontal, three-row pages, as in the supplied recording.
function cashbackRows(){return state.cashbackRates.map((c,i)=>`<button class="cashback-line" data-action="category" data-category="${esc(c.name)}"><span class="cashback-category-icon tone-${i%4}">${icon(c.icon)}<b>${c.rate}%</b></span><span><strong>${esc(c.name)}</strong><small>${c.rate}% власні кошти</small></span><i class="${state.categories.includes(c.name)?'chosen':''}">${state.categories.includes(c.name)?'✓':'+'}</i></button>`).join('')}
cashbackPage=function(){return `<div class="cashback-page"><header class="cashback-gradient ${cashbackExpanded?'expanded':''}"><div class="cashback-toolbar"><button data-action="back" aria-label="Назад">${icon('arrow-left')}</button><button class="cashback-balance-toggle" data-action="cashback-expand" aria-label="Розгорнути баланс кешбеку">${displayMoney(state.cashback)} ₴</button><button data-action="cashback-info" aria-label="Про кешбек">${icon('question')}</button></div><div class="cashback-head-carousel"><section><h1>Баланс кешбеку</h1><strong>${displayMoney(state.cashback)} ₴</strong><p>Накопичено ${displayMoney(state.cashback)} ₴<br>Демонстраційний баланс</p></section><section><h1>Усього накопичено кешбеку</h1><strong>${displayMoney(state.cashbackEarned??state.cashback)} ₴</strong><p>За даними демо-проєкту</p></section></div><div class="cashback-head-actions"><button data-action="cashback-info">${icon('gift-fill')}Задонатити на благо</button><button data-action="cashback-info">${icon('receipt')}Архів</button></div></header><div class="cashback-body"><div class="cashback-switch"><button data-action="cashback-tab" data-tab="cashback" class="${cashbackTab==='cashback'?'selected':''}">${icon('gift-fill')}Кешбек</button><button data-action="cashback-tab" data-tab="points" class="${cashbackTab==='points'?'selected':''}">Пундики</button></div>${cashbackTab==='cashback'?`<div class="cashback-heading"><h2>Кешбек від банку</h2><button data-action="cashback-all">Див. усі</button></div><p class="cashback-card-type">За картками Visa</p><div class="cashback-category-pages">${Array.from({length:Math.ceil(state.cashbackRates.length/3)},(_,i)=>`<div>${cashbackRows().split('</button>').slice(i*3,i*3+3).filter(Boolean).map(s=>s+'</button>').join('')}</div>`).join('')}</div><div class="cashback-heading"><h2>Кешбек від партнерів</h2><button data-action="cashback-info">Див. усі</button></div><div class="partner-list">${(state.cashbackPartners||[]).map(p=>`<button class="cashback-line" data-action="cashback-info"><span class="cashback-category-icon tone-0">${icon('gift-fill')}<b>${Number(p.rate)}%</b></span><span><strong>${esc(p.name)}</strong><small>${esc(p.note||'')}</small></span><i>+</i></button>`).join('')}</div>`:empty('Пундики','У демо ще немає нарахувань.','gift-fill')}</div></div>`};
actions['cashback-expand']=()=>{cashbackExpanded=!cashbackExpanded;$('.cashback-gradient')?.classList.toggle('expanded',cashbackExpanded)};
actions['cashback-tab']=b=>{cashbackTab=b.dataset.tab;render()};actions['cashback-info']=()=>inform('Кешбек','Демонстраційні суми та категорії задаються в адмінці. Реальні виплати й пожертви не виконуються.');actions['cashback-all']=()=>{modal('Категорії кешбеку','<div class="all-cashback-categories">'+cashbackRows()+'</div>',null)};
function notificationsPage(){return toolbar('',`<button class="right" data-action="notification-search" aria-label="Пошук повідомлень">${icon('magnifying-glass')}</button>`)+`<div class="page notification-page"><h1>Повідомлення</h1><div class="notification-shortcuts"><button data-action="notification-info"><span>${icon('receipt')}</span>Умови та<br>правила</button><button data-action="notification-info"><span>${icon('gift-fill')}</span>Оновлення<br>кешбеку</button></div><h2>Всі прочитані</h2><div id="notification-list">${(state.notificationsList||[]).map(n=>`<button class="notification-row" data-action="notification-info" data-id="${esc(n.id)}"><span class="service-symbol ${esc(n.color||'orange')}">${icon(n.icon||'gift-fill')}</span><span><strong>${esc(n.title)}</strong><small>${esc(n.text)}</small></span></button>`).join('')}</div></div>`}
actions['notification-info']=()=>inform('Повідомлення','Це повідомлення демонстраційного проєкту.');actions['notification-search']=()=>inform('Пошук повідомлень','Повідомленнями демо керують в адмінці.');
const surfacesHome=home;home=function(){return surfacesHome().replace('data-page="support" aria-label="Підтримка"','data-page="notifications" aria-label="Повідомлення"')};
const products=[{id:'phone-one',name:'Смартфон Apple',price:157999,image:'assets/reference/product-0.png'},{id:'phone-two',name:'Смартфон Apple',price:117999,image:'assets/reference/product-1.png'}];
market=function(){return `<div class="market-page"><div class="search">${icon('magnifying-glass')}<input id="market-search" placeholder="Пошук" aria-label="Пошук товарів"></div><img class="market-banner" src="assets/reference/market-banner.png" alt="Банер каталогу з відеореференсу"><div class="market-categories">${['Всі категорії','Смартфони та гаджети','ТВ, Аудіо та Фото','Apple','Побутова техніка','Ноутбуки та комп’ютери'].map((name,i)=>`<button data-action="market-category" data-category="${name}"><img src="assets/reference/market-category-${i}.png" alt=""><span>${name}</span></button>`).join('')}</div><h2>Ви переглядали</h2><div class="market-products">${products.map(p=>`<button data-action="offer" data-title="${p.name}"><img src="${p.image}" alt="${p.name}"><span>★★★★★</span><strong>${p.name}</strong><b>${displayMoney(p.price)} ₴</b></button>`).join('')}</div><div class="market-demo-caption">Демонстраційний каталог · оформлення покупок недоступне</div></div>`};
actions['market-category']=b=>inform(b.dataset.category,'Демонстраційний каталог із наданого відео. Замовлення не оформлюються.');
const surfaces={personal:personalPage,cardDetails:cardDetailsPage,statement:statementPage,subscriptions:subscriptionsPage,platinum:platinumPage,notifications:notificationsPage,photoChoice:()=>photoChoicePage(false),poster:()=>photoChoicePage(true)};
const beforeSurfaces=render;
render=function(){if(!adminMode&&surfaces[route.page]){defaults();$('#app').className=route.page;$('#nav').hidden=true;$('#screen').innerHTML=surfaces[route.page]();bindStatement()}else beforeSurfaces();if(!adminMode){if(['appearance','cashback'].includes(route.page))$('#nav').hidden=true;if($('#market-search'))$('#market-search').oninput=e=>document.querySelectorAll('.market-products>button').forEach(b=>b.hidden=!b.innerText.toLowerCase().includes(e.target.value.toLowerCase()));if(route.page==='cashback')window.requestAnimationFrame(()=>{const header=$('.cashback-gradient');if(header)header.style.setProperty('--cashback-collapse',Math.min(1,pageScrollY()/120))})}};
const originalDefaults=defaults;
defaults=function(){originalDefaults();for(const key of ['subscriptions','notificationsList','cashbackPartners'])if(!Array.isArray(state[key]))state[key]=[]};
const previousAdminPage=adminPage;
adminPage=function(){let html=previousAdminPage(),extra='';if(adminTab==='contacts'){extra=`<div class="admin-section-title"><h2>Підписки та сервіси</h2>${adminButton('admin-subscription','Додати підписку')}</div>${state.subscriptions.map(s=>adminRow(esc(s.title),esc(s.date),adminButton('admin-subscription','Змінити',s.id,'pencil-simple')+adminButton('admin-delete-subscription','Видалити',s.id,'trash'))).join('')}<div class="admin-section-title"><h2>Повідомлення</h2>${adminButton('admin-notification','Додати повідомлення')}</div>${state.notificationsList.map(n=>adminRow(esc(n.title),esc(n.text),adminButton('admin-notification','Змінити',n.id,'pencil-simple')+adminButton('admin-delete-notification','Видалити',n.id,'trash'))).join('')}`}if(adminTab==='profile')extra=`<div class="admin-section-title"><h2>Партнери кешбеку</h2>${adminButton('admin-partner','Додати партнера')}</div>${state.cashbackPartners.map(p=>adminRow(esc(p.name),p.rate+'% · '+esc(p.note||''),adminButton('admin-partner','Змінити',p.id,'pencil-simple')+adminButton('admin-delete-partner','Видалити',p.id,'trash'))).join('')}`;if(extra){const at=html.lastIndexOf('</section>');html=html.slice(0,at)+extra+html.slice(at)}return html};
const newAdminActions={
 'admin-subscription':b=>adminSimpleForm('subscriptions',b.dataset.id,'Підписка',s=>field('Назва сервісу','title',s.title||'','text','required maxlength="80"')+field('Дата токена','date',s.date||today(),'date','required'),f=>({title:f.get('title').trim(),date:f.get('date')})),
 'admin-delete-subscription':b=>removeItem('subscriptions',b.dataset.id,'Видалити підписку?'),
 'admin-notification':b=>adminSimpleForm('notificationsList',b.dataset.id,'Повідомлення',n=>field('Заголовок','title',n.title||'','text','required maxlength="100"')+field('Текст','text',n.text||'','text','required maxlength="500"'),f=>({title:f.get('title').trim(),text:f.get('text').trim()})),
 'admin-delete-notification':b=>removeItem('notificationsList',b.dataset.id,'Видалити повідомлення?'),
 'admin-partner':b=>adminSimpleForm('cashbackPartners',b.dataset.id,'Партнер кешбеку',p=>field('Назва','name',p.name||'','text','required maxlength="80"')+field('Кешбек, %','rate',p.rate||1,'number','required min="0" max="100" step="0.01"')+field('Опис','note',p.note||'','text','maxlength="150"'),f=>({name:f.get('name').trim(),rate:Number(f.get('rate')),note:f.get('note')})),
 'admin-delete-partner':b=>removeItem('cashbackPartners',b.dataset.id,'Видалити партнера?')
};
for(const [key,fn] of Object.entries(newAdminActions))actions[key]=(...args)=>{if(!adminMode)return;return fn(...args)};
window.addEventListener('scroll',()=>{if(route.page==='home'){const y=pageScrollY();$('#app').classList.toggle('home-scrolled',y>160)}if(route.page==='cashback')$('.cashback-gradient')?.style.setProperty('--cashback-collapse',Math.min(1,pageScrollY()/120))},{passive:true});
const bankNavigation=nav;
nav=function(){if(route.page!=='market')return bankNavigation();return `<div class="market-mini-tabs">${[['bank','Банк','cards-native'],['home','Головна','bag-fill'],['profile','Кабінет','users'],['cart','Кошик','shopping-bag-fill'],['bazar','Базар','chat-circle-fill']].map(([id,label,i])=>`<button data-action="market-nav" data-section="${id}" class="${id==='home'?'selected':''}">${uiIcon(i)}<span>${label}</span></button>`).join('')}</div>`};
actions['market-nav']=b=>{const section=b.dataset.section;if(section==='bank')navigate('home');else if(section==='home')pageScrollTo({top:0,behavior:shouldReduceMotion()?'instant':'smooth'});else if(section==='profile')navigate('personal');else inform(section==='cart'?'Кошик':'monobazar · BETA',section==='cart'?'У демо-каталозі замовлення не оформлюються.':'Демонстраційний екран маркетплейсу. Оголошення не публікуються.')};
render();
